SELECT bai.account_item_id, bai.account_item_name, IFNULL( SUM( bbpd.principal_amount ), 0 ) AS totalAmount FROM base_account_item bai LEFT JOIN ( SELECT bbpd.account_item_id, bbpd.principal_amount FROM base_bill_pay_detail bbpd,( SELECT bbp.bill_pay_id FROM base_bill_pay bbp,( SELECT bb.org_id, bb.bill_id, bb.bill_date FROM base_bill bb
and bb.bill_date IS NOT NULL and bb.bill_num IS NOT NULL
and bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( bb.bill_date, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y' ) <= #{query.endDate}
GROUP BY bb.bill_id ) bb WHERE bbp.org_id = bb.org_id AND bbp.bill_id = bb.bill_id AND bbp.payee_date = bb.bill_date GROUP BY bbp.bill_pay_id ) bbp WHERE bbpd.bill_pay_id = bbp.bill_pay_id GROUP BY bbpd.bill_pay_detail_record_id ) bbpd ON bai.account_item_id = bbpd.account_item_id GROUP BY bai.account_type_id, bai.account_item_id ORDER BY bai.account_type_id, bai.account_item_id

