GROUP BY bbp.bill_pay_id ) bbp WHERE bbpd.bill_pay_id = bbp.bill_pay_id GROUP BY bbpd.bill_pay_detail_record_id ) bbpd ON bai.account_item_id = bbpd.account_item_id GROUP BY bai.account_type_id, bai.account_item_id ORDER BY bai.account_type_id, bai.account_item_id

